CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visitors (id TEXT PRIMARY KEY,first_seen INTEGER NOT NULL,last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS days (day TEXT NOT NULL,visitor TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,is_returning INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,visitor));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,ts INTEGER NOT NULL,visitor TEXT NOT NULL,session TEXT NOT NULL,kind TEXT NOT NULL,sport TEXT NOT NULL,section TEXT NOT NULL,entity TEXT NOT NULL,country TEXT NOT NULL,state TEXT NOT NULL,device TEXT NOT NULL,source TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_ts ON events(ts);
CREATE INDEX IF NOT EXISTS events_visitor_ts ON events(visitor,ts);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,visitor TEXT NOT NULL,started INTEGER NOT NULL,last_seen INTEGER NOT NULL,section TEXT NOT NULL,country TEXT NOT NULL,state TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_seen ON sessions(last_seen);
CREATE INDEX IF NOT EXISTS sessions_visitor_seen ON sessions(visitor,last_seen DESC);
CREATE TABLE IF NOT EXISTS limits (key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
